components.css:
.ds-placa {
  appearance: none;
  border: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3.1rem;
  padding: 0.55rem 1.15rem 0.45rem;
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.4rem;
  letter-spacing: -0.03em;
  line-height: 1;
  border-radius: 2px;
  background: var(--lime);
  color: var(--night);
  text-decoration: none;
}
.ds-placa:hover { background: var(--lime-deep); }
.ds-placa:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
.ds-placa:disabled {
  background: var(--purple-deep);
  color: var(--ink-dim);
  box-shadow: inset 0 0 0 1px var(--jamb);
  cursor: not-allowed;
}

.ds-vidro {
  appearance: none;
  border: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3.1rem;
  padding: 0.55rem 1.15rem 0.45rem;
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.4rem;
  letter-spacing: -0.03em;
  line-height: 1;
  border-radius: 2px;
  background: transparent;
  color: var(--ink);
  text-decoration: none;
  box-shadow: inset 0 0 0 1px var(--ink-dim);
}
.ds-vidro:hover { background: var(--purple-deep); }
.ds-vidro:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
.ds-vidro:disabled {
  background: var(--purple-deep);
  color: var(--ink-dim);
  box-shadow: inset 0 0 0 1px var(--jamb);
  cursor: not-allowed;
}

.ds-off {
  appearance: none;
  border: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3.1rem;
  padding: 0.55rem 1.15rem 0.45rem;
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.4rem;
  letter-spacing: -0.03em;
  line-height: 1;
  border-radius: 2px;
  background: var(--purple-deep);
  color: var(--ink-dim);
  box-shadow: inset 0 0 0 1px var(--jamb);
  cursor: not-allowed;
}

.ds-field { display: grid; gap: 0.3rem; max-width: 28rem; }
.ds-field-nome {
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.45rem;
  letter-spacing: -0.03em;
  color: var(--ink);
}
.ds-field-nome small {
  font-family: var(--body);
  font-weight: 400;
  font-size: 0.95rem;
  color: var(--ink-dim);
  margin-left: 0.35rem;
}
.ds-controle { position: relative; }
.ds-adorn {
  position: absolute;
  left: 0.85rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--lime);
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.25rem;
  pointer-events: none;
}
.ds-field input {
  width: 100%;
  min-height: 3.25rem;
  padding: 0.65rem 0.9rem 0.55rem 3.1rem;
  border: 1px solid var(--jamb);
  border-radius: 2px;
  background: var(--night-2);
  color: var(--ink);
  font-family: var(--body);
  font-size: 1.2rem;
  font-variant-numeric: tabular-nums;
  caret-color: var(--lime);
}
.ds-field input:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
.ds-field input[aria-invalid="true"] { border-color: var(--fault); }
.ds-ajuda { color: var(--ink-dim); margin: 0; font-family: var(--body); font-size: 0.98rem; }

.ds-fascia {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.7rem 1.4rem;
  padding: 0.95rem clamp(1.1rem, 4vw, 2.5rem) 0.8rem;
  background: var(--purple);
  color: var(--ink);
  box-shadow: 0 12px 28px rgba(6, 4, 8, 0.35);
}
.ds-tubo {
  position: absolute;
  left: 0; right: 0; top: 0;
  height: 4px;
  background: var(--lime);
  transform-origin: left center;
  animation: ds-acende 900ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.ds-marca {
  font-family: var(--display);
  font-weight: 800;
  font-size: 2.4rem;
  letter-spacing: -0.035em;
  line-height: 0.9;
  color: var(--ink);
  text-decoration: none;
}
.ds-fascia nav { display: flex; flex-wrap: wrap; gap: 0.35rem 1.15rem; }
.ds-fascia nav a {
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.35rem;
  letter-spacing: -0.03em;
  text-decoration: none;
  color: var(--ink);
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
}
.ds-fascia nav a:hover,
.ds-fascia nav a[aria-current="page"] {
  color: var(--lime);
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 0.28em;
}
.ds-fascia nav a:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
@keyframes ds-acende { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@media (prefers-reduced-motion: reduce) {
  .ds-tubo { animation: none; }
}

.ds-resultado {
  position: relative;
  background: var(--purple-deep);
  color: var(--ink);
  padding: 1.25rem 1.25rem 1.4rem;
  box-shadow: 0 18px 36px rgba(6, 4, 8, 0.38);
  max-width: 24rem;
}
.ds-tubo-fixo {
  display: block;
  height: 4px;
  margin: -1.25rem -1.25rem 1rem;
  background: var(--lime);
}
.ds-rotulo {
  margin: 0;
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.35rem;
  letter-spacing: -0.03em;
}
.ds-preco {
  margin: 0.15rem 0 0.4rem;
  font-family: var(--display);
  font-weight: 800;
  font-size: clamp(3.4rem, 8vw, 5.6rem);
  letter-spacing: -0.045em;
  line-height: 0.86;
  color: var(--lime);
  font-variant-numeric: tabular-nums;
  animation: ds-assenta 420ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-custo-linha { margin: 0.35rem 0 0.8rem; color: var(--ink-dim); font-family: var(--body); }
.ds-custo-linha strong { color: var(--ink); font-weight: 700; }
.ds-barra { display: flex; height: 0.85rem; margin: 1rem 0 0; background: var(--night); overflow: hidden; }
.ds-barra span { display: block; height: 100%; }
.ds-seg-custo { width: 80%; background: var(--custo); }
.ds-seg-imposto { width: 10%; background: var(--imposto); }
.ds-seg-margem { width: 10%; background: var(--lime); }
@keyframes ds-assenta {
  from { transform: translateY(0.4rem); filter: blur(5px); }
  to { transform: none; filter: none; }
}
@media (prefers-reduced-motion: reduce) {
  .ds-preco { animation: none; }
}

.ds-rail-frame { position: relative; height: 5.75rem; background: var(--night); }
.ds-dock {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem clamp(1.1rem, 4vw, 2.5rem) calc(0.75rem + env(safe-area-inset-bottom));
  background: var(--purple-deep);
  border-top: 4px solid var(--lime);
  box-shadow: 0 -14px 30px rgba(6, 4, 8, 0.45);
}
.ds-dock span {
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: -0.03em;
  color: var(--ink);
}
.ds-dock strong {
  font-family: var(--display);
  font-weight: 800;
  font-size: 2.1rem;
  line-height: 0.9;
  letter-spacing: -0.04em;
  color: var(--lime);
  font-variant-numeric: tabular-nums;
}

.ds-janela {
  position: relative;
  background: var(--purple-deep);
  aspect-ratio: 16 / 9;
  min-height: 10rem;
}
.ds-janela::before {
  content: "";
  position: absolute;
  z-index: 1;
  left: 0; right: 0; top: 0;
  height: 4px;
  background: var(--lime);
}

.ds-canais { display: grid; gap: 0.8rem; }
.ds-canais a {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  text-decoration: none;
  padding: 1rem 0 0.8rem;
  border-top: 1px solid rgba(213, 204, 226, 0.35);
  font-family: var(--display);
  font-weight: 800;
  font-size: clamp(2rem, 5vw, 3.2rem);
  letter-spacing: -0.04em;
  line-height: 0.95;
  color: var(--ink);
}
.ds-canais a span {
  font-family: var(--body);
  font-weight: 400;
  font-size: 1rem;
  letter-spacing: 0;
  color: var(--ink-dim);
}
.ds-canais a:hover { color: var(--lime); }
.ds-canais a:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
